#!/usr/bin/env python3
"""Apply end-to-end C++ function identity fixes for CI validation."""

from __future__ import annotations

from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"expected exactly one match in {path}, found {count}")
    p.write_text(text.replace(old, new, 1))


replace_once(
    "decbench/models/decompilation.py",
    '''        with open(path, "w") as f:\n            for func in self.functions.values():\n                f.write(f"// Function: {func.name} @ 0x{func.address:x}\\n")\n                f.write(func.decompiled_code)\n                f.write("\\n\\n")\n''',
    '''        with open(path, "w") as f:\n            for storage_key, func in self.functions.items():\n                f.write(f"// Function: {storage_key} @ 0x{func.address:x}\\n")\n                f.write(func.decompiled_code)\n                f.write("\\n\\n")\n''',
)

replace_once(
    "decbench/metrics/byte_match.py",
    '''import logging\nimport re\nfrom pathlib import Path\n''',
    '''import logging\nimport re\nfrom collections import Counter\nfrom pathlib import Path\n''',
)

replace_once(
    "decbench/metrics/byte_match.py",
    '''        context_decls = derive_context_decls(\n            {name: fd.decompiled_code or "" for name, fd in decompilation.functions.items()}\n        )\n''',
    '''        # Storage keys may be address-qualified (``foo@0x...``), while\n        # prototype recovery needs the semantic C identifier.  A same-name\n        # collision is intentionally omitted: choosing either overload's\n        # signature for calls to the other would conflate distinct functions.\n        name_counts = Counter(fd.name for fd in decompilation.functions.values())\n        context_decls = derive_context_decls(\n            {\n                fd.name: fd.decompiled_code or ""\n                for fd in decompilation.functions.values()\n                if name_counts[fd.name] == 1\n            }\n        )\n''',
)

replace_once(
    "decbench/scoring/report_extras.py",
    '''def _lookup_source_ex(\n    decompile_results: Any,\n    project: str,\n    opt_level: Any,\n    binary: str,\n    func_name: str,\n) -> tuple[str | None, str]:\n    """Best-effort source text + provenance/miss status for one function."""\n    bp = _lookup_binary_path(decompile_results, project, opt_level, binary)\n    if bp is None:\n        return None, "binary_not_found"\n    try:\n        from decbench.utils.source_extract import function_source_ex\n\n        return function_source_ex(Path(bp), func_name)\n    except Exception:\n        return None, "extract_failed"\n''',
    '''def _lookup_function_by_storage_key(\n    decompile_results: Any,\n    project: str,\n    opt_level: Any,\n    binary: str,\n    storage_key: str,\n) -> Any:\n    """Resolve a serialized metric/storage key back to its semantic function."""\n    if not decompile_results:\n        return None\n    try:\n        opt_results = decompile_results.get(project) or {}\n        binary_results = opt_results.get(opt_level)\n        if binary_results is None:\n            ov = _opt_value(opt_level)\n            for key, val in opt_results.items():\n                if _opt_value(key) == ov:\n                    binary_results = val\n                    break\n        if not binary_results:\n            return None\n        for dec_result in (binary_results.get(binary) or {}).values():\n            func = (getattr(dec_result, "functions", None) or {}).get(storage_key)\n            if func is not None:\n                return func\n    except Exception:\n        return None\n    return None\n\n\ndef _lookup_source_ex(\n    decompile_results: Any,\n    project: str,\n    opt_level: Any,\n    binary: str,\n    func_name: str,\n) -> tuple[str | None, str]:\n    """Best-effort source text + provenance/miss status for one function.\n\n    ``func_name`` is the benchmark storage key.  For collision-qualified C++\n    keys, recover the semantic source name and canonical address from any\n    decompiler result before asking the source extractor to disambiguate DWARF.\n    """\n    bp = _lookup_binary_path(decompile_results, project, opt_level, binary)\n    if bp is None:\n        return None, "binary_not_found"\n    try:\n        from decbench.utils.source_extract import function_source_ex\n\n        func = _lookup_function_by_storage_key(\n            decompile_results, project, opt_level, binary, func_name\n        )\n        if func is not None:\n            return function_source_ex(Path(bp), func.name, func.address)\n        return function_source_ex(Path(bp), func_name)\n    except Exception:\n        return None, "extract_failed"\n''',
)

Path("tests/test_cpp_identity_end_to_end.py").write_text(
    '''"""End-to-end regressions for collision-qualified C++ function identity."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom decbench.metrics.byte_match import ByteMatchMetric\nfrom decbench.models.decompilation import (\n    DecompilationResult,\n    DecompilerMetadata,\n    FunctionDecompilation,\n)\nfrom decbench.models.metrics import MetricValue\nfrom decbench.scoring import report_extras\nfrom decbench.utils import results_tree, source_extract\n\n\ndef _result(tmp_path: Path) -> DecompilationResult:\n    result = DecompilationResult(\n        binary_path=tmp_path / "fixture",\n        binary_name="fixture",\n        decompiler=DecompilerMetadata(decompiler_name="fixture-dec"),\n    )\n    result.add_function(\n        FunctionDecompilation(\n            name="same",\n            address=0x1000,\n            decompiled_code="int same(int x) { return x + 1; }",\n        )\n    )\n    result.add_function(\n        FunctionDecompilation(\n            name="same",\n            address=0x2000,\n            decompiled_code="double same(double x) { return x + 2.0; }",\n        )\n    )\n    result.add_function(\n        FunctionDecompilation(\n            name="unique",\n            address=0x3000,\n            decompiled_code="int unique(void) { return 3; }",\n        )\n    )\n    return result\n\n\ndef test_c_artifact_round_trip_preserves_collision_storage_keys(tmp_path: Path) -> None:\n    result = _result(tmp_path)\n    artifact = tmp_path / "fixture.c"\n    result.to_c_file(artifact)\n\n    blocks = results_tree.split_functions(artifact)\n    assert set(blocks) == {"same@0x1000", "same@0x2000", "unique"}\n    assert blocks["same@0x1000"][0] == 0x1000\n    assert blocks["same@0x2000"][0] == 0x2000\n    assert blocks["unique"][0] == 0x3000\n\n    text = artifact.read_text()\n    assert "// Function: same@0x1000 @ 0x1000" in text\n    assert "// Function: same@0x2000 @ 0x2000" in text\n    assert "// Function: unique @ 0x3000" in text\n\n\ndef test_sample_set_reader_keeps_collision_storage_keys(tmp_path: Path) -> None:\n    result = _result(tmp_path)\n    decompiled = tmp_path / "O2" / "proj" / "decompiled"\n    decompiled.mkdir(parents=True)\n    result.to_c_file(decompiled / "fixture-dec_fixture.c")\n\n    reader = report_extras.SampleSetReader(tmp_path)\n    blocks = reader.decompiled("O2", "proj", "fixture", "fixture-dec")\n    assert set(blocks) == {"same@0x1000", "same@0x2000", "unique"}\n\n\ndef test_report_source_lookup_uses_semantic_name_and_address(\n    tmp_path: Path, monkeypatch\n) -> None:\n    result = _result(tmp_path)\n    nested = {"proj": {"O2": {"fixture": {"fixture-dec": result}}}}\n    seen: list[tuple[Path, str, int | None]] = []\n\n    def fake_source(\n        binary_path: Path | None, func_name: str, func_address: int | None = None\n    ) -> tuple[str | None, str]:\n        assert binary_path is not None\n        seen.append((Path(binary_path), func_name, func_address))\n        return "source", "source"\n\n    monkeypatch.setattr(source_extract, "function_source_ex", fake_source)\n    source, status = report_extras._lookup_source_ex(\n        nested, "proj", "O2", "fixture", "same@0x1000"\n    )\n\n    assert (source, status) == ("source", "source")\n    assert seen == [(result.binary_path, "same", 0x1000)]\n\n\ndef test_report_source_lookup_keeps_legacy_plain_name_fallback(\n    tmp_path: Path, monkeypatch\n) -> None:\n    result = _result(tmp_path)\n    nested = {"proj": {"O2": {"fixture": {"fixture-dec": result}}}}\n    seen: list[tuple[str, int | None]] = []\n\n    def fake_source(\n        _binary_path: Path | None, func_name: str, func_address: int | None = None\n    ) -> tuple[str | None, str]:\n        seen.append((func_name, func_address))\n        return "source", "source"\n\n    monkeypatch.setattr(source_extract, "function_source_ex", fake_source)\n    report_extras._lookup_source_ex(nested, "proj", "O2", "fixture", "unique")\n    assert seen == [("unique", 0x3000)]\n\n\ndef test_byte_match_context_uses_only_unambiguous_semantic_names(\n    tmp_path: Path, monkeypatch\n) -> None:\n    result = _result(tmp_path)\n    captured: dict[str, str] = {}\n\n    def fake_derive(function_codes: dict[str, str]) -> dict[str, str]:\n        captured.update(function_codes)\n        return {"unique": "int unique(void);"}\n\n    monkeypatch.setattr("decbench.metrics.fixup.derive_context_decls", fake_derive)\n    metric = ByteMatchMetric()\n\n    def fake_compute(*_args, **_kwargs) -> MetricValue:\n        return MetricValue(value=1.0)\n\n    monkeypatch.setattr(metric, "compute_for_function", fake_compute)\n    metric.compute_for_binary(result)\n\n    assert set(captured) == {"unique"}\n    assert "same@0x1000" not in captured\n    assert "same@0x2000" not in captured\n    assert "same" not in captured\n'''
)
